import {windsOfMagic,affiliatedCareer,collegeCareer,collegeLore,collegeLores,startingScryer,psychometrySacrifice,womReferences,quoteRitual,mundaneAlchemist} from './winds-of-magic.mjs';
import {derive} from './rules.mjs';
import {creationSpecies} from './origins.mjs';
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function collegePanel(R,s){
 if(!windsOfMagic(R)||!affiliatedCareer(s))return '';
 return `<section class="notice"><strong>College affiliation · Winds of Magic p. 35</strong>${collegeCareer(s)?`<p>${esc(collegeLore(s))} · fixed by this Career.</p>`:`<div class="field"><label for="college-lore">College Lore</label><select id="college-lore" data-bind="college"><option value="">Choose…</option>${collegeLores.map(l=>`<option value="${l}" ${s.college===l?'selected':''}>${l}</option>`).join('')}</select></div>`}<p class="small">Your first Arcane Magic Talent must match your College. Follow its traditions and arcane marks; later Elf Lores still follow Fifth Edition’s requirements.</p></section>`;
}
export function psychometryPanel(R,s){
 if(!windsOfMagic(R)||s.species!=='Human')return '';
 if(startingScryer(s))return '<div class="notice">Starting Scryer: Psychometry is a normal Career Skill option. Allocate your eight free Advances as usual; no Species Talent sacrifice is required (Winds of Magic p. 48).</div>';
 const count=creationSpecies(R,s).randomTalents;
 if(!count)return '<p class="small muted">This origin has no random Species Talent to trade for Psychometry (Winds of Magic p. 48).</p>';
 const blocked=derive(R,s).skills.Augury>0;
 return `<details class="section-gap" ${s.psychometrySlot!==undefined?'open':''}><summary>Optional Psychometry · Winds of Magic p. 48</summary><p class="small">Give up one random Species Talent to unlock paid Psychometry advancement. This grants no free points. Advancement requires one of the printed magical or religious Careers; non-career prices apply. Augury and Psychometry are mutually exclusive.</p>${!s.randomTalents.length?'<p class="small muted">Roll your random Species Talents first.</p>':`<div class="field"><label for="psychometry-talent">Species Talent to give up</label><select id="psychometry-talent" data-bind="psychometrySlot"><option value="">Keep all random Talents</option>${s.randomTalents.map((t,i)=>`<option value="${i}" ${s.psychometrySlot===i?'selected':''} ${blocked||s.originTalentSlot===`random-${i}`?'disabled':''}>${esc(t)}${s.originTalentSlot===`random-${i}`?' · already replaced':''}</option>`).join('')}</select>${blocked?'<p class="purchase-error">You already have an Augury Advance; you cannot also take Psychometry.</p>':''}</div>`}${psychometrySacrifice(R,s)?`<p class="small">${esc(s.randomTalents[s.psychometrySlot])} is removed from your Talent grants. Its original roll remains in your dice record.</p>`:''}</details>`;
}
export function psychicSkillPanel(R,s){return !windsOfMagic(R)?'':`<details class="section-gap"><summary>Augury & Psychometry · Winds of Magic pp. 44–48</summary>${R.skills.filter(x=>['Augury','Psychometry'].includes(x.name)).map(x=>`<p><strong>${x.name} (${x.char})</strong> · p. ${x.page}<br>${esc(x.text)}</p>`).join('')}<p>Augury becomes a first-level option for Mystic; Nun with Morr or Sigmar; and Priest or Warrior Priest with Morr. Choose the matching Bless/Invoke patron in Talents to expose those conditional options. Starting Astromancers already have Augury in their Career.</p><p>Other Humans can trade one random Species Talent in Talents for paid Psychometry access. Starting Scryers need no trade.</p></details>`;}
export function womReferencePanel(R,s){return womReferences(R,s).map(x=>`<div class="notice"><strong>Winds of Magic p. ${x.source.page}</strong><p class="small">${esc(x.text)}</p></div>`).join('');}
export function pettyGrantNote(R,s,g){return windsOfMagic(R)&&mundaneAlchemist(s)&&g.talent==='Petty Magic'?'<p class="small muted">Mundane Alchemist: choose only Bearings, Open Lock, Shock and Warning. Your free grant is the smaller of your Willpower Bonus when you learned Petty Magic or four, using the approved Fifth Edition adaptation (Winds of Magic p. 39; core p. 123).</p>':'';}
export function womGearPanel(R){
 if(!windsOfMagic(R))return '';
 return `<details class="section-gap"><summary>Wizard robes & enchanted staffs · Winds of Magic pp. 151–152</summary>${R.gear.filter(x=>x.source.book==='winds-of-magic'&&['Wizard robes','Magical artefacts'].includes(x.category)).map(x=>`<p><strong>${esc(x.name)}</strong> · p. ${x.page}<br>${esc(x.text)}</p>`).join('')}<p class="small">Robes can be bought in Gear & money → Shop at their printed second-hand illicit-market prices. Staff commissioning is deferred; learning Imbue Staff does not create an item in this character creator.</p></details>`;
}
export function ritualShop(R,s,creationErrors=[]){
 if(!windsOfMagic(R))return '';
 return `<details class="section-gap"><summary>Learn rituals · Winds of Magic pp. 27–33</summary><p class="small">Memorising a ritual uses its own printed XP cost and earns no tracker box. It does not count as a spell toward new-spell prices, extra Elf Lores or Cants. Performing rituals, sacrifices and resulting creatures/items are deferred.</p>${R.spells.filter(x=>x.ritual).map(x=>{const q=quoteRitual(R,s,x.name),reason=q.error||(creationErrors.length?'Finish creation before spending XP.':'');return `<div class="xp-row"><details><summary>${esc(x.name)} <span class="source">p. ${x.page}</span></summary><p>${esc(x.text)}</p></details><div><button type="button" class="primary" data-action="buy-spell" data-name="${esc(x.name)}" data-talent="${esc(q.talent)}" ${reason?'disabled':''}>${q.cost} XP</button>${reason?`<p class="purchase-error minilabel">${esc(reason)}</p>`:''}</div></div>`;}).join('')}</details>`;
}
